#!/usr/bin/env node
/**
 * Regenerate src/research/files.ts by inlining every .md from the
 * canonical fixture workspace at
 * @agentproto/corpus/test/fixtures/research.
 *
 * The fixture dir is the SINGLE source of truth — files.ts is a build
 * artifact, untracked from git, regenerated by predev / prebuild /
 * precheck-types / pretest hooks. Editing the preset means editing
 * the fixtures; the next build picks it up. Never commit files.ts.
 *
 * The conformance test enforces those .md files validate against the
 * actual AgentProto JSON Schemas, so what ships in the preset is
 * always AIP-conformant by construction.
 *
 * Manual regen (rarely needed): `pnpm gen:research`.
 */

import { readFileSync, readdirSync, statSync, writeFileSync } from "node:fs"
import path from "node:path"
import { fileURLToPath } from "node:url"

const __dirname = path.dirname(fileURLToPath(import.meta.url))
// scripts/ → corpus-presets/ → packages/ → corpus/test/fixtures/research
const FIXTURE_ROOT = path.resolve(
  __dirname,
  "../../corpus/test/fixtures/research"
)
const OUT = path.resolve(__dirname, "../src/research/files.ts")

function walk(dir, files = []) {
  for (const ent of readdirSync(dir)) {
    const full = path.join(dir, ent)
    const s = statSync(full)
    if (s.isDirectory()) walk(full, files)
    else if (ent.endsWith(".md")) {
      const rel = path.relative(FIXTURE_ROOT, full).split(path.sep).join("/")
      files.push({ rel, content: readFileSync(full, "utf8") })
    }
  }
  return files
}

const all = walk(FIXTURE_ROOT).sort((a, b) => a.rel.localeCompare(b.rel))

const lines = []
lines.push("/**")
lines.push(" * AUTO-GENERATED build artifact — DO NOT COMMIT, DO NOT EDIT.")
lines.push(" *")
lines.push(" * Regenerated from @agentproto/corpus/test/fixtures/research/")
lines.push(" * by the prebuild / precheck-types / pretest / predev hooks on")
lines.push(" * this package. To change the preset content, edit the fixtures.")
lines.push(" */")
lines.push("")
lines.push(
  "export const RESEARCH_PRESET_FILES: Readonly<Record<string, string>> = Object.freeze({"
)
for (const { rel, content } of all) {
  lines.push(`  ${JSON.stringify(rel)}: ${JSON.stringify(content)},`)
}
lines.push("})")
lines.push("")

writeFileSync(OUT, lines.join("\n"))
console.log(`Wrote ${all.length} files to ${OUT}`)
